<script setup lang="ts">
import {ref,watch,computed,onBeforeUnmount} from 'vue';
import {messageKey,decrypt,unb64,aad} from './protectedCrypto';
const props=defineProps<{chat:number;message:any;review:boolean;download:string}>();
const cipherPreview=computed(()=>{try{return String(JSON.parse(props.message.protected_payload).ciphertext).slice(0,144).match(/.{1,12}/g)?.join(' ')||'';}catch{return '';}});
const payloadKey=computed(()=>{try{return JSON.parse(props.message.protected_payload).key_id as string;}catch{return '';}});
const emit=defineEmits<{unlock:[key:string]}>();
const content=ref<any>(null),url=ref(''),error=ref(''),loading=ref(false);let version=0;
function clear(){if(url.value)URL.revokeObjectURL(url.value);url.value='';content.value=null;}
watch(()=>[messageKey(props.chat,payloadKey.value),props.chat,props.review,props.message.protected_payload],()=>{const key=!props.review?messageKey(props.chat,payloadKey.value):undefined;const stamp=++version;clear();error.value='';if(!key)return;const message=props.message;void(async()=>{try{const payload=JSON.parse(message.protected_payload);const decoded=JSON.parse(new TextDecoder().decode(await decrypt(key,payload.iv,payload.ciphertext,aad(props.chat,message.protected_uuid,'message'))));if(stamp===version)content.value=decoded;}catch{if(stamp===version)error.value='Unable to unlock this message. The key or encrypted content does not match.';}})();},{immediate:true});
async function file(){const key=messageKey(props.chat,payloadKey.value);if(!key||props.review||!content.value?.file)return;const stamp=version;loading.value=true;try{const response=await fetch(props.download,{headers:{Accept:'application/octet-stream'}});if(!response.ok)throw new Error('Unable to load the encrypted file.');const p=JSON.parse(props.message.protected_payload);const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(p.file_iv),additionalData:aad(props.chat,props.message.protected_uuid,'file'),tagLength:128},key,await response.arrayBuffer());if(stamp===version)url.value=URL.createObjectURL(new Blob([bytes],{type:content.value.file.type||'application/octet-stream'}));}catch{if(stamp===version)error.value='Unable to authenticate or unlock this file.';}finally{loading.value=false;}}
onBeforeUnmount(()=>{version++;clear();});
</script>
<template><div class="protected-message"><small v-if="content">Protected message</small><template v-if="content"><p>{{content.body}}</p><template v-if="content.file"><button v-if="!url" type="button" :disabled="loading" @click="file">{{loading?'Unlocking file...':'Open '+content.file.name}}</button><template v-else><img v-if="/^image\/(jpeg|png|webp)$/.test(content.file.type)" :src="url" :alt="content.file.name" style="max-width:260px;max-height:260px"><audio v-if="/^audio\//.test(content.file.type)||/\.(webm|ogg|m4a)$/i.test(content.file.name)" :src="url" controls/><a :href="url" :download="content.file.name">Download {{content.file.name}}</a></template></template></template><template v-else><div class="protected-locked"><span class="protected-lock-icon" aria-hidden="true"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/></svg></span><div><strong>Private message</strong><code v-if="review" class="protected-cipher" aria-label="Encrypted message">{{cipherPreview}}</code><p>{{review?'Protected content is not available in conversation review.':'Unlock with the access key shared by Super Admin.'}}</p><button v-if="!review" type="button" class="protected-unlock" @click="emit('unlock',payloadKey)">Unlock message <span aria-hidden="true">&rarr;</span></button></div></div></template><p v-if="error" role="alert">{{error}}</p></div></template>
<style scoped>
.protected-message{min-width:0}.protected-message small{font-weight:600;opacity:.7}.protected-message a{display:block;margin-top:8px}.protected-message audio{max-width:250px}.protected-message button{padding:7px;border-radius:6px;background:transparent;color:inherit;border:1px solid currentColor}.protected-locked{display:flex;align-items:flex-start;gap:12px;padding:10px 6px;max-width:310px}.protected-lock-icon{display:grid;place-items:center;flex:0 0 38px;height:38px;border-radius:12px;background:var(--comm-soft,#e8f5f0);color:var(--comm-accent,#128c76)}.protected-locked strong{font-size:13px;line-height:1.5}.protected-locked p{font-size:12px!important;line-height:1.55!important;color:var(--muted,#737373);margin:4px 0 10px!important}.protected-locked .protected-unlock{border:0;padding:0;background:none;font-size:12px;font-weight:600;color:var(--comm-accent,#128c76);cursor:pointer;display:flex;gap:12px;align-items:center;min-height:26px}.protected-unlock:focus-visible{outline:2px solid currentColor;outline-offset:3px}
.protected-cipher{display:block;font:11px/1.8 ui-monospace,monospace;overflow-wrap:anywhere;white-space:normal;margin:8px 0;opacity:.7;user-select:text}</style>
